import{_ as i,C as s,o as r,c as n,a5 as e,j as l,E as c}from"./chunks/framework.a5no_H3L.js";const y=JSON.parse('{"title":"虚函数表与 RTTI：还原 C++ 类结构","description":"C++ 程序编译后，会留下两个独特的结构：虚函数表（vtable） 和 RTTI（运行时类型信息）。它们是还原 C++ 类结构的钥匙——从 vtable 能看出类的虚函数，从 RTTI 能看出类的名字和继承关系。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md","filePath":"reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"}'),d={name:"reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"},p={"data-src-line":"12","data-src-file":"reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"};function h(g,a,v,o,b,k){const t=s("SvgDiagram");return r(),n("div",null,[a[0]||(a[0]=e('<h1 id="虚函数表与-rtti-还原-c-类结构" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">虚函数表与 RTTI：还原 C++ 类结构 <a class="header-anchor" href="#虚函数表与-rtti-还原-c-类结构" aria-label="Permalink to &quot;虚函数表与 RTTI：还原 C++ 类结构&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">C++ 程序编译后，会留下两个独特的结构：<strong>虚函数表（vtable）</strong> 和 <strong>RTTI（运行时类型信息）</strong>。它们是还原 C++ 类结构的钥匙——从 vtable 能看出类的虚函数，从 RTTI 能看出类的名字和继承关系。</p><h2 id="_1-虚函数是怎么实现的" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">1. 虚函数是怎么实现的 <a class="header-anchor" href="#_1-虚函数是怎么实现的" aria-label="Permalink to &quot;1. 虚函数是怎么实现的&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">C++ 的多态靠虚函数实现。编译后，每个有虚函数的类，都有一张<strong>虚函数表（vtable）</strong>：一个函数指针数组，按声明顺序存放所有虚函数的地址。</p><p data-src-line="10" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">每个对象实例的第一个字段（通常），是一个指向 vtable 的指针（vptr）。调用虚函数时，程序通过「对象 → vptr → vtable → 函数指针」这三级间接跳转，找到实际要调用的函数。</p>',5)),l("p",p,[c(t,{src:"/reverse-engineering/05-static-analysis-chapter-03-vtable.svg",alt:"虚函数调用：对象经 vptr 指向 vtable，再由 vtable 里的函数指针跳转到实际函数实现"})]),a[1]||(a[1]=e(`<p data-src-line="14" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">这套机制解释了「为什么调用同一个函数名，实际执行的代码不同」——因为 vtable 里的指针，被子类替换成了自己的实现。</p><h2 id="_2-反汇编里识别-vtable" tabindex="-1" data-src-line="16" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">2. 反汇编里识别 vtable <a class="header-anchor" href="#_2-反汇编里识别-vtable" aria-label="Permalink to &quot;2. 反汇编里识别 vtable&quot;">​</a></h2><p data-src-line="18" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">识别 vtable 有两个特征：</p><p data-src-line="20" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"><strong>构造函数里写 vptr</strong>。C++ 对象的构造函数，开头会把自己类的 vtable 地址写进对象：</p><div class="language-asm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rcx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], offset vtable_ClassName   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">; 把 vtable 地址写进对象开头</span></span></code></pre></div><p data-src-line="26" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">看到「往对象开头写一个地址，而这个地址指向一张函数指针表」，基本就是「构造函数初始化 vptr」。</p><p data-src-line="28" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"><strong>间接调用</strong>。虚函数调用是间接的：</p><div class="language-asm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  rax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rcx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">; 取 vptr（对象第一个字段）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">call</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> qword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ptr [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">; 调 vtable 第 2 项（第二个虚函数）</span></span></code></pre></div><p data-src-line="35" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">看到「先取对象开头的指针，再按偏移间接 call」，就是虚函数调用。<code>[rax+8]</code> 说明是第二个虚函数。</p><h2 id="_3-rtti-运行时类型信息" tabindex="-1" data-src-line="37" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">3. RTTI：运行时类型信息 <a class="header-anchor" href="#_3-rtti-运行时类型信息" aria-label="Permalink to &quot;3. RTTI：运行时类型信息&quot;">​</a></h2><p data-src-line="39" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">C++ 的 <code>typeid</code> 和 <code>dynamic_cast</code> 需要运行时知道对象的真实类型，这就是 <strong>RTTI</strong> 提供的信息。</p><p data-src-line="41" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">RTTI 结构里，对逆向最有价值的是<strong>类的名字</strong>——它以字符串形式存在二进制里（MSVC 下形如 <code>.?AVClassName@@</code>）。反汇编器（IDA、Ghidra）能解析 RTTI，自动恢复出类名。</p><p data-src-line="43" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">RTTI 还编码了<strong>继承关系</strong>：基类列表、继承层级。通过 RTTI，能还原出「类 A 继承自类 B」这种关系。</p><h2 id="_4-从-vtable-rtti-还原类结构" tabindex="-1" data-src-line="45" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">4. 从 vtable + RTTI 还原类结构 <a class="header-anchor" href="#_4-从-vtable-rtti-还原类结构" aria-label="Permalink to &quot;4. 从 vtable + RTTI 还原类结构&quot;">​</a></h2><p data-src-line="47" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">把 vtable 和 RTTI 结合起来，能还原出一个 C++ 类的完整面貌：</p><ol data-src-line="49" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"><li data-src-line="49" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"><strong>类名</strong>：从 RTTI 字符串得到。</li><li data-src-line="50" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"><strong>虚函数列表</strong>：从 vtable 得到（每个函数指针是一个虚函数，顺序对应声明顺序）。</li><li data-src-line="51" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"><strong>成员布局</strong>：从构造函数的「基址 + 偏移」访问得到（上一章的方法）。</li><li data-src-line="52" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"><strong>继承关系</strong>：从 RTTI 的基类列表得到。</li></ol><p data-src-line="54" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">这些信息拼起来，你就能把一个「无名结构体 + 一堆函数指针」还原成「<code>class Foo : public Bar</code>，有这些成员、这些虚函数」。</p><h2 id="_5-还原的实践顺序" tabindex="-1" data-src-line="56" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">5. 还原的实践顺序 <a class="header-anchor" href="#_5-还原的实践顺序" aria-label="Permalink to &quot;5. 还原的实践顺序&quot;">​</a></h2><p data-src-line="58" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">分析一个 C++ 程序时，建议按这个顺序还原类结构：</p><ol data-src-line="60" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"><li data-src-line="60" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">先让反汇编器解析 RTTI，得到类名（自动完成）。</li><li data-src-line="61" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">定位构造函数，识别 vptr 写入和成员初始化。</li><li data-src-line="62" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">从 vtable 读出虚函数列表，逐个分析虚函数。</li><li data-src-line="63" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">结合上一章的方法，恢复成员布局。</li><li data-src-line="64" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">把类名、虚函数、成员重命名到反编译产物里。</li></ol><p data-src-line="66" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">这样反编译产物会从「一堆 <code>v1</code>、<code>sub_xxx</code>」变成「<code>Foo::bar()</code>、<code>this-&gt;field</code>」的可读代码。</p><hr><blockquote data-src-line="70" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md"><p data-src-line="70" data-src-file="reverse-engineering/05-static-analysis/chapter-03-vtable-rtti.md">本章建立的是 C++ 类结构的还原方法：vtable 暴露虚函数，RTTI 暴露类名和继承关系，两者结合还原类结构。这为分析 C++ 商业软件打基础。下一阶段进入<a href="./../06-dynamic-debugging/chapter-01-debugging-basics.html">动态调试</a>。</p></blockquote>`,23))])}const f=i(d,[["render",h]]);export{y as __pageData,f as default};
